package com.johnny.hotel.repair;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequiredArgsConstructor@RequestMapping("/api/repair-orders")@PreAuthorize("hasAnyRole('STAFF','FINANCE','MANAGER','OWNER','SUPER_ADMIN')")public class RepairOrderController{private final RepairOrderService service;@GetMapping public Result<PageResult<RepairOrder>> list(@RequestParam(required=false)Long roomId,@RequestParam(required=false)Integer status,@RequestParam(required=false)Long inspectionId,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(service.list(roomId,status,inspectionId,page,pageSize));}@GetMapping("/{id}")public Result<RepairOrder> get(@PathVariable Long id){return Result.success(service.get(id));}@PostMapping("/{id}/complete")@PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')")public Result<RepairOrder> complete(@PathVariable Long id,@Valid@RequestBody(required=false)RepairRequests.Complete request){return Result.success(service.complete(id,request,false));}@PostMapping("/{id}/force-complete")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<RepairOrder> force(@PathVariable Long id,@Valid@RequestBody(required=false)RepairRequests.Complete request){return Result.success(service.complete(id,request,true));}@PostMapping("/{id}/cancel")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<RepairOrder> cancel(@PathVariable Long id,@RequestBody(required=false)RepairRequests.Complete request){return Result.success(service.cancel(id,request==null?null:request.getNotes()));}}
